// src/services/core/userInfo.service.ts
var USER_INFO_SVC = "UserInfoService";
var UserInfoService = class _UserInfoService extends Service {
  constructor() {
    super();
    this.userColors = ["#c22828", "#ce471d", "#c62582", "#9b4cE7", "#a15e9d", "#7065bd", "#5565f1", "#1b70e0", "#3778b9", "#547d66", "#218500", "#1c6f3c"];
    this.userColorNames = ["purple-lavender", "purple-violet", "red-coral", "blue-jeanlouisdavid", "green-mint", "green-yellow", "orange-jade", "pink-lady", "yellow-submarine", "blue-teal"];
    this.logger = LoggerService.getInstance();
    this.settingsService = SettingsService.getInstance();
  }
  static {
    __name(this, "UserInfoService");
  }
  static getInstance() {
    return Service.create(USER_INFO_SVC, _UserInfoService);
  }
  static build() {
    return new _UserInfoService();
  }
  getAvatarImage(objId, initials, color, size, lastAvatarUpdate) {
    lastAvatarUpdate = typeof lastAvatarUpdate === "undefined" ? false : lastAvatarUpdate;
    if (!lastAvatarUpdate) return initials ? this.createDefaultAvatarImage(initials, color) : null;
    const serverURL = config.webservices.protocol + "://" + config.webservices.currentServer;
    let src = serverURL + "/api/avatar/" + objId + "?size=" + (size ? size : 256);
    if (lastAvatarUpdate) {
      src += "&update=" + MainService.MD5(lastAvatarUpdate);
    }
    return { src };
  }
  getNameInformation(firstName, lastName) {
    const result = { displayName: "", initials: "" };
    if (lastName.length !== 1 && firstName.length !== 2) {
      if (this.settingsService.getSetting("displayOrder") === "FL") {
        result.displayName = firstName + " " + lastName;
        result.initials = firstName.charAt(0).toUpperCase() + lastName.charAt(0).toUpperCase();
      } else {
        result.displayName = lastName + " " + firstName;
        result.initials = lastName.charAt(0).toUpperCase() + firstName.charAt(0).toUpperCase();
      }
    } else {
      if (this.settingsService.getSetting("displayOrder") === "FL") {
        result.displayName = firstName + " " + lastName;
      } else {
        result.displayName = lastName + " " + firstName;
      }
      result.initials = firstName.charAt(0).toUpperCase() + firstName.charAt(1).toUpperCase();
    }
    return result;
  }
  createDefaultAvatarImage(initials, color) {
    const image = new Image();
    const canvas = document.createElement("canvas");
    canvas.width = image.width = 225;
    canvas.height = image.height = 225;
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      throw new Error("failed to get 2d context");
    }
    ctx.rect(0, 0, 225, 225);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.font = "bold 100px Helvetica";
    ctx.textAlign = "center";
    ctx.fillStyle = "white";
    ctx.fillText(initials, 110, 150);
    image.src = canvas.toDataURL("image/png");
    return image;
  }
  computeUserColor(displayName) {
    const result = { colorIndex: 0, color: this.userColors[0], colorName: this.userColorNames[0] };
    try {
      const upperCaseDisplayName = displayName.toUpperCase();
      let sum = 0;
      for (let i = 0; i < upperCaseDisplayName.length; i++) {
        sum += upperCaseDisplayName.charCodeAt(i);
      }
      result.colorIndex = sum % 12;
      result.color = this.userColors[result.colorIndex];
      result.colorName = this.userColorNames[result.colorIndex];
    } catch (error) {
      this.logger.error("[UserInfoService] computeUserColor failure");
      result.colorIndex = 1;
      result.color = this.userColors[result.colorIndex];
      result.colorName = this.userColorNames[result.colorIndex];
    }
    return result;
  }
};

// src/services/core/company.service.ts
var COMPANY_SVC = "CompanyService";
var CompanyService = class _CompanyService extends Service {
  constructor() {
    super();
    this.eventService = EventService.getInstance();
    this.logger = LoggerService.getInstance();
    this.authService = AuthService.getInstance();
    this.userInfoService = UserInfoService.getInstance();
    this.xmppService = XmppService.getInstance();
    this.errorHelperService = ErrorHelperService.getInstance();
    this.companies = {};
    this.xmppService.subscribeToConnectionEvents((event) => {
      if (event.name === "ON_XMPP_DISCONNECTED" && event.data.reason === "LOGOUT") {
        this.companies = {};
      }
    });
    setTimeout(() => {
      this.configure();
    }, 500);
  }
  static {
    __name(this, "CompanyService");
  }
  static getInstance() {
    return Service.create(COMPANY_SVC, _CompanyService);
  }
  static build() {
    return new _CompanyService();
  }
  configure() {
    this.eventService.subscribe("ON_COMPANY_CHANGE_EVENT", (__event, companyId) => {
      this.getCompanyById(companyId, true);
    });
  }
  async getCompanyById(companyId, update = false) {
    try {
      if (!companyId) {
        throw new Error("missing companyId");
      }
      let company = this.companies[companyId];
      if (company && !update) {
        this.logger.info("[companyService] getCompanyById (cache) " + companyId + " - success");
        return company;
      }
      const headers = this.authService.getRequestHeader();
      let url = `${config.restServerUrl}/api/rainbow/enduser/v1.0/companies/${companyId}`;
      url += "?selectedThemeObj=true";
      const responseData = await fetch(url, { method: "GET", headers });
      if (!responseData.ok) {
        throw new Error(responseData.statusText);
      }
      const companyData = await responseData.json();
      if (company) {
        company.updateFromData(companyData.data);
        this.logger.info(`getCompanyById (update) ${companyId} - success`);
      } else {
        company = Company.createFromData(companyData.data);
        this.companies[company.id] = company;
        this.logger.info(`getCompanyById ${companyId} - success`);
      }
      this.getCompanyLogo(company);
      this.getCompanyBanner(company);
      return company;
    } catch (error) {
      const errorMessage = `getCompanyById -- FAILURE -- ${error.message}`;
      this.logger.error(errorMessage);
      throw new Error(errorMessage);
    }
  }
  async searchCompanies(searchText, hasBP = null, isBP = null, bpType = null) {
    try {
      let url = `${config.restServerUrl}/api/rainbow/enduser/v1.0/companies?name=${encodeURIComponent(searchText)}&format=full`;
      if (hasBP !== void 0 && hasBP !== null) {
        url += "&hasBP=" + hasBP;
      }
      if (isBP !== void 0 && isBP !== null) {
        url += "&isBP=" + isBP;
      }
      if (bpType) {
        url += "&bpType=" + bpType;
      }
      const headers = this.authService.getRequestHeader();
      const responseData = await fetch(url, { method: "GET", headers });
      if (!responseData.ok) {
        throw new Error(responseData.statusText);
      }
      const companiesData = await responseData.json();
      const companies = companiesData.data.reduce((result, companyData) => {
        if (companyData.name !== "Default" && companyData.name !== "Rainbow" && companyData.status === "active") {
          let company = this.companies[companyData.id];
          if (!company) {
            company = Company.createFromData(companyData);
            this.companies[company.id] = company;
            this.getCompanyLogo(company);
          }
          result.push(company);
        }
        return result;
      }, []);
      this.logger.info("searchCompanies with criteria '" + searchText + "' - success - found " + companiesData.length + " companies : returns " + companies.length + " companies");
      return companies;
    } catch (error) {
      const errorMessage = `searchCompanies -- FAILURE -- ${error.message}`;
      this.logger.error(errorMessage);
      throw new Error(errorMessage);
    }
  }
  async getCompanyAdminsData(companyId) {
    try {
      let url = `${config.restServerUrl}/api/rainbow/enduser/v1.0/companies/${companyId}/administrators`;
      url += "?selectedThemeObj=true";
      const headers = this.authService.getRequestHeader();
      const responseData = await fetch(url, { method: "GET", headers });
      if (!responseData.ok) {
        throw new Error(responseData.statusText);
      }
      const data = (await responseData.json()).data;
      return data;
    } catch (error) {
      const errorMessage = `getCompanyAdminsData -- FAILURE -- ${error.message}`;
      this.logger.error(errorMessage);
      throw new Error(errorMessage);
    }
  }
  async getCompanyUsers(companyId, pageSize) {
    try {
      const url = `${config.restServerUrl}/api/rainbow/search/v1.0/users?companyId=${companyId}&limit=${pageSize}`;
      const headers = this.authService.getRequestHeader();
      const responseData = await fetch(url, { method: "GET", headers });
      if (!responseData.ok) {
        throw new Error(responseData.statusText);
      }
    } catch (error) {
      const errorMessage = `getCompanyUsers -- FAILURE -- ${error.message}`;
      this.logger.error(errorMessage);
      throw new Error(errorMessage);
    }
  }
  async getCompanyLogo(company) {
    try {
      const companyColor = this.userInfoService.computeUserColor(company.name);
      const companyInitials = company.name.substr(0, 1);
      company.logo = this.userInfoService.getAvatarImage(company.id, companyInitials, companyColor.color, 130, company.lastAvatarUpdateDate);
      this.eventService.publish("ON_COMPANY_LOGO_UPDATED", company.id);
      this.logger.info("[getCompanyLogo] - " + company.getNameForLogs() + " - success");
      company.sendChangeEvent("logo");
      return company;
    } catch (error) {
      throw new Error(`getCompanyLogo -- FAILURE -- ${error.message}`);
    }
  }
  async getCompanyBanner(company) {
    return new Promise((resolve) => {
      const image = new Image();
      image.onload = () => {
        company.banner = image;
        this.eventService.publish("ON_COMPANY_BANNER_UPDATED", company.id);
        this.logger.info("[getCompanyBanner] - " + company.getNameForLogs() + " - success");
        resolve(company);
      };
      image.onerror = () => {
        this.logger.error("[companyService] Load banner for " + company.getNameForLogs() + " failure");
        resolve(company);
      };
      let imgSrc = config.sdk ? null : "/cacheV2/images/company-banner-01.svg";
      if (company.lastBannerUpdateDate) {
        const serverURL = config.webservices.protocol + "://" + config.webservices.currentServer;
        imgSrc = serverURL + "/api/banner/" + company.id + "?size=831";
        imgSrc += "&update=" + MainService.MD5(company.lastBannerUpdateDate);
      }
      if (imgSrc) {
        image.src = imgSrc;
      } else resolve(company);
    });
  }
  async getImageMimeType(imageUrl) {
    try {
      if (!imageUrl) {
        return null;
      }
      const responseData = await fetch(imageUrl);
      if (!responseData.ok) {
        throw new Error(responseData.statusText);
      }
      const blob = await responseData.blob();
      return blob.type;
    } catch (error) {
      const errorMessage = `getImageMimeType -- FAILURE -- ${error.message}`;
      this.logger.error(errorMessage);
      return null;
    }
  }
  async getCompanyFeatures(companyId) {
    try {
      const features = { alertNotifAllowed: false, webinarAccess: false };
      const url = `${config.restServerUrl}/api/rainbow/subscription/v1.0/companies/${companyId}/subscriptions/features`;
      const headers = this.authService.getRequestHeader();
      const responseData = await fetch(url, { method: "GET", headers });
      if (!responseData.ok) {
        throw new Error(responseData.statusText);
      }
      const data = (await responseData.json()).data;
      const featureAlertNotifAllowed = data.find((feat) => {
        return feat.featureUniqueRef === "ALERT_NOTIFICATIONS_ALLOWED";
      });
      if (featureAlertNotifAllowed) {
        features.alertNotifAllowed = featureAlertNotifAllowed.isEnabled;
      }
      const featureWebinarAccess = data.find((feat) => {
        return feat.featureUniqueRef === "WEBINAR_ACCESS";
      });
      if (featureWebinarAccess) {
        features.webinarAccess = featureWebinarAccess.isEnabled;
      }
      return features;
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "getCompanyFeatures");
      this.logger.warn(`[companyService] ${errorInfo.message}`);
      return {};
    }
  }
};

// src/utils/promiseQueue.ts
var PromiseQueue = class _PromiseQueue {
  constructor() {
    this.queue = [];
    this.started = false;
    this.logger = LoggerService.getInstance();
  }
  static {
    __name(this, "PromiseQueue");
  }
  static create() {
    return new _PromiseQueue();
  }
  add(promise) {
    this.queue.push(promise);
    if (!this.started) {
      this.started = true;
      this.execute();
    }
  }
  execute() {
    const promise = this.queue.shift();
    if (promise) {
      try {
        this.timeoutPromise(2e4, promise).then(() => {
          this.execute();
        }).catch((error) => {
          const errorMessage = error?.message ? error.message : "unknownError";
          this.logger.error(`[PromiseQueue] execute failure -- ${errorMessage}`);
          this.execute();
        });
      } catch (error) {
        const errorMessage = error?.message ? error.message : "unknownError";
        const errorStack = error?.stack ? error.stack : "Unknown stack";
        this.logger.error(`[PromiseQueue] execution exception  -- ${errorMessage} : ${errorStack}`);
        this.execute();
      }
    } else {
      this.started = false;
    }
  }
  timeoutPromise(ms, promise) {
    let timeoutId = null;
    const timeout = new Promise((__resolve, reject) => {
      timeoutId = setTimeout(() => {
        reject(new Error("Timed out in " + ms + "ms."));
      }, ms);
    });
    return Promise.race([promise(), timeout]).then((value) => {
      clearTimeout(timeoutId);
      return value;
    });
  }
};

