  // User PHONE NUMBERS stuff
  // --------------------------------
  get phoneNumbers() {
    const phoneNumbers = [];
    if (this.phonePbx && !this.phonePro) {
      phoneNumbers.push({ type: "businessPhone" /* BUSINESS */, number: this.phonePbx });
    }
    if (this.phonePro && this.phoneProCan) {
      phoneNumbers.push({ type: "businessPhone" /* BUSINESS */, number: this.phoneProCan });
    }
    if (this.businessPhones?.length) {
      this.businessPhones.forEach((businessPhone) => {
        if (businessPhone?.length > 0) {
          phoneNumbers.push({ type: "businessPhone" /* BUSINESS */, number: businessPhone });
        }
      });
    }
    if (this.mobilePro && this.mobileProCan) {
      phoneNumbers.push({ type: "businessMobilePhone" /* BUSINESS_MOBILE */, number: this.mobileProCan, shared: this.isMobileProShared });
    }
    if (this.mobilePhones?.length) {
      this.mobilePhones.forEach((mobilePhone) => {
        if (mobilePhone?.length > 0) {
          phoneNumbers.push({ type: "businessMobilePhone" /* BUSINESS_MOBILE */, number: mobilePhone });
        }
      });
    }
    if (this.phoneInternalNumber) {
      phoneNumbers.push({ type: "businessInternalPhone" /* BUSINESS_INTERNAL */, number: this.phoneInternalNumber });
    }
    if (this.phonePerso && this.phonePersoCan) {
      phoneNumbers.push({ type: "personalPhone" /* PERSONAL */, number: this.phonePersoCan, shared: this.isPhonePersoShared });
    }
    if (this.mobilePerso && this.mobilePersoCan) {
      phoneNumbers.push({ type: "personalMobilePhone" /* PERSONAL_MOBILE */, number: this.mobilePersoCan, shared: this.isMobilePersoShared });
    }
    if (this.otherPhoneNumbers?.length && this.otherPhoneNumbers?.forEach) {
      this.otherPhoneNumbers.forEach((otherPhone) => {
        if (otherPhone?.length > 0) {
          phoneNumbers.push({ type: "otherPhone" /* OTHER */, number: otherPhone });
        }
      });
    }
    return phoneNumbers;
  }
