  async getApiConfigurationFromServer() {
    try {
      const url = `${config.restServerUrl}/api/rainbow/enduser/v1.0/settings/apis`;
      const headers = this.authService.getRequestHeader();
      const response = await fetch(url, { method: "GET", headers });
      if (!response.ok) throw response;
      const responseData = await response.json();
      this.logger.info(`[ContactService] getApiConfigurationFromServer success`);
      const httpUrls = [];
      if (responseData?.data?.additionalHeaders) {
        responseData.data.additionalHeaders.forEach((additionalHeader) => {
          additionalHeader.match.forEach((obj) => {
            httpUrls.push({
              "url": obj.url.replace("*", ""),
              "method": obj.method,
              "headers": additionalHeader.headers
            });
          });
        });
      }
      this.mainService.apiHeadersConfiguration = httpUrls;
      this.apiConfigTTL = responseData.data.ttl;
      if (this.apiConfigTTL) {
        this.apiConfigTTLTimeout = setTimeout(() => {
          this.apiConfigTTL = 0;
          this.getApiConfigurationFromServer();
        }, this.apiConfigTTL * 1e3);
      }
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "getApiConfigurationFromServer");
      this.logger.error(errorInfo.message);
    }
  }
