  /* ******************************************************************* */
  /* * LIFECYCLE STUFF                                                 * */
  /* ******************************************************************* */
  static getInstance() {
    return Service.create(PROFILE_SVC, _ProfileService);
  }
  static build() {
    return new _ProfileService();
  }
  async start() {
    try {
      this.logger.info("");
      this.logger.info("[profileService] === STARTING ===");
      this.attachHandlers();
      await this.getServerProfile();
      this.started = true;
      this.logger.info("[profileService] === STARTED ===");
      this.rxSubject.next(RBEvent.create(_ProfileService.PROFILE_FEATURES_UPDATE));
    } catch (error) {
      this.logger.info(`[profileService] === STARTING FAILURE === ${error.message}`);
      throw error;
    }
  }
  async stop() {
    this.logger.info("[profileService] === STOPPING ===");
    this.detachHandlers();
    this.started = false;
    this.thirdPartyApps = null;
    this.sdkApiKeys = void 0;
    this.logger.info("[profileService] === STOPPED ===");
  }
  reconnect() {
    this.restart();
  }
  restart() {
    this.logger.info("[profileService] === RESTART ===");
    this.attachHandlers();
    this.onUserUpdateNeeded();
  }
  subscribe(handler) {
    return this.rxSubject.subscribe(handler);
  }
  attachHandlers() {
    this.detachHandlers();
    this.logger.info("[profileService] attachHandlers");
    this.profileEventHandler = this.xmppService.addHandler((stanza) => {
      return this.onManagementMessageReceived(stanza);
    }, null, "message", "management");
  }
  detachHandlers() {
    this.logger.info("[profileService] detachHandlers");
    if (this.profileEventHandler) {
      this.xmppService.deleteHandler(this.profileEventHandler);
      this.profileEventHandler = null;
    }
  }
  onManagementMessageReceived(stanza) {
    try {
      const userprofileElem = xmlParser_default(stanza).find("userprofile");
      if (userprofileElem.length) {
        this.logger.info("[profileService] onManagementMessageReceived  -- on userprofile management message received");
        switch (userprofileElem.attr("action")) {
          case "create":
          case "update":
          case "delete":
            this.onUserUpdateNeeded();
            break;
          default:
            this.logger.info("[profileService] onManagementMessageReceived  -- unknown action");
            break;
        }
      }
      return true;
    } catch (error) {
      this.logger.error(`[profileService] onManagementMessageReceived ERROR ${error}`);
      return true;
    }
  }
  onUserUpdateNeeded() {
    if (this.timer) {
      return;
    }
    this.timer = setTimeout(async () => {
      try {
        await this.contactService.updateContactFromServer(this.contactService.userContact, true);
        await this.getServerProfile();
        this.rxSubject.next(RBEvent.create(_ProfileService.PROFILE_FEATURES_UPDATE));
        this.timer = null;
      } catch (error) {
        this.timer = null;
        this.logger.info(`[profileService] === onUserUpdateNeeded FAILURE === ${error.message}`);
      }
    }, 3e3);
  }
  /* ****************************************************************** */
  /* * PROFILE API STUFF                                              * */
  /* ****************************************************************** */
  getServerProfile() {
    return Promise.all([this.getServerProfiles(), this.getServerProfilesFeatures()]);
  }
  async getServerProfiles() {
    try {
      const url = `${config.restServerUrl}/api/rainbow/enduser/v1.0/users/${this.contactService.userContact.dbId}/profiles`;
      const headers = this.authService.getRequestHeader();
      const response = await fetch(url, { method: "GET", headers });
      if (!response.ok) {
        throw response;
      }
      const responseData = await response.json();
      this.profiles = [];
      this.mainOffers = [];
      responseData.data.forEach((profileData) => {
        this.logger.debug(`[profileService] getServerProfiles === response === ${profileData}`);
        this.profiles.push(profileData);
        const offer = Offer.createFromProfileData(profileData);
        if (offer.isExclusive || offer.isDefault) {
          this.mainOffers.push(offer);
        }
      });
      this.mainOffers.sort(Offer.offerComparator);
    } catch (error) {
      let errorMessage = "getServerProfiles failure: no server response";
      if (error) {
        errorMessage = "getServerProfiles failure: " + JSON.stringify(error);
      }
      this.logger.error("[profileService] " + errorMessage);
      throw new Error(errorMessage);
    }
  }
  async getServerProfilesFeatures() {
    try {
      const url = `${config.restServerUrl}/api/rainbow/enduser/v1.0/users/${this.contactService.userContact.dbId}/profiles/features`;
      const headers = this.authService.getRequestHeader();
      const response = await fetch(url, { method: "GET", headers });
      if (!response.ok) {
        throw response;
      }
      const responseData = await response.json();
      this.features = {};
      responseData.data.forEach((featureData) => {
        this.logger.debug(`[profileService] getServerProfilesFeatures === ${featureData.featureUniqueRef}${featureData.featureType === "boolean" ? " isEnabled:" + featureData.isEnabled : ""}${featureData.featureType === "number" && featureData["limitMin"] ? "limitMin:" + featureData.limitMin + " " : " "}${featureData.featureType === "number" && featureData["limitMax"] ? "limitMax:" + featureData.limitMax : ""}`);
        if (featureData.hasOwnProperty("featureUniqueRef")) {
          this.features[featureData.featureUniqueRef] = featureData;
        }
      });
      if (this.features[this.FeaturesEnum.TELEPHONY_SOFTPHONE_NOT_ALLOWED]?.isEnabled) {
        this.logger.debug(`[profileService] getServerProfilesFeatures === TELEPHONY_SOFTPHONE_NOT_ALLOWED => LOGOUT`);
        this.telsoftPhoneNotAllowed.next(true);
      }
      const userContact = this.contactService.userContact;
      userContact.attendantConsoleEnabled = // voice attendant
      userContact.pbxId && userContact.isVoiceSubscriber() && (this.features.hasOwnProperty(this.FeaturesEnum.TELEPHONY_BASIC_ATTENDANT_CONSOLE) && this.features[this.FeaturesEnum.TELEPHONY_BASIC_ATTENDANT_CONSOLE].isEnabled || config[this.FeaturesEnum.TELEPHONY_BASIC_ATTENDANT_CONSOLE]) || // hybrid attendant
      userContact.pbxId && !userContact.isVoiceSubscriber() && (this.features.hasOwnProperty(this.FeaturesEnum.TELEPHONY_HYBRID_ATTENDANT_CONSOLE) && this.features[this.FeaturesEnum.TELEPHONY_HYBRID_ATTENDANT_CONSOLE].isEnabled || config[this.FeaturesEnum.TELEPHONY_HYBRID_ATTENDANT_CONSOLE]);
      userContact.supervisorConsoleEnabled = userContact.pbxId && userContact.isSupervisor() && (this.features.hasOwnProperty(this.FeaturesEnum.SUPERVISION_GROUP_SHOW_CONSOLE) && this.features[this.FeaturesEnum.SUPERVISION_GROUP_SHOW_CONSOLE].isEnabled || config[this.FeaturesEnum.SUPERVISION_GROUP_SHOW_CONSOLE]);
      userContact.generalizedAttendantLookForUsers = !userContact.attendantConsoleEnabled && userContact.pbxId && userContact.isVoiceSubscriber() && this.features.hasOwnProperty(this.FeaturesEnum.TELEPHONY_MAX_CALL) && this.features[this.FeaturesEnum.TELEPHONY_MAX_CALL]?.limitMax > 2;
      this.logger.debug(`[profileService] getServerProfilesFeatures / generalizedAttendantLookForUsers: ` + userContact.generalizedAttendantLookForUsers + " TELEPHONY_MAX_CALL = " + this.features[this.FeaturesEnum.TELEPHONY_MAX_CALL]?.limitMax);
    } catch (error) {
      let errorMessage = "getServerProfilesFeatures failure: no server response";
      if (error) {
        errorMessage = `getServerProfilesFeatures failure: ${JSON.stringify(error)}`;
      }
      this.logger.error("[profileService] " + errorMessage);
      throw new Error(errorMessage);
    }
  }
