  ///           MANAGE PUBLIC DOWNLOADS             ///
  getPublicFileDownloads() {
    return this.publicFileDownload;
  }
  clearPublicFileDownloads() {
    this.publicFileDownload = [];
  }
  findPublicFileDownload(fileUrl) {
    return this.publicFileDownload.find((element) => {
      return element.url === fileUrl;
    });
  }
  updatePublicFileDownloadArray(filesPublicDownload, fileSystem) {
    this.logger.info("[FileStorageService] >updatePublicFileDownloadArray");
    filesPublicDownload.forEach((element) => {
      const fileDownload = this.findPublicFileDownload(element["url"]);
      if (fileDownload) {
        this.logger.info("[FileStorageService] file (" + element["url"] + ") Found - to update");
        fileDownload.receivedBytes = element["receivedBytes"];
        fileDownload.savePath = element["savePath"];
        if (fileDownload.isDownloadFinished() && fileDownload.openFolderOnceDownloadFinished) {
          this.logger.debug("[FileStorageService] showItemInFolder auto on download completion");
          fileSystem.showItemInFolder(fileDownload.savePath);
        }
        this.logger.debug("[FileStorageService] fileName=" + fileDownload.fileName);
        this.logger.debug("[FileStorageService] file receivedBytes=" + fileDownload.receivedBytes);
        this.logger.debug("[FileStorageService] file totalBytes=" + fileDownload.totalBytes);
        this.logger.debug("[FileStorageService] file savePath=" + fileDownload.savePath);
        fileDownload.progressSubject.next(void 0);
      } else {
        this.logger.info("[FileStorageService] file Not Found");
        const newFile = FilePublicDownload.create(element["url"], element["fileName"], element["totalBytes"], element["receivedBytes"], element["savePath"]);
        this.publicFileDownload.unshift(newFile);
      }
      this.publicFileDownloadSubject.next(void 0);
    });
  }
  getUploadingFilesSize() {
    let filesSize = 0;
    this.uploadingFileDescriptors.forEach((fileDescriptor) => {
      filesSize += fileDescriptor.size;
    });
    return filesSize;
  }
  removeUploadingFileFromId(fileId) {
    const file = this.uploadingFileDescriptors.find((fileDesc) => {
      return fileDesc.id === fileId;
    });
    if (file) this.removeUploadingFileDescriptor(file);
  }
  removeUploadingFileDescriptor(fileDesc) {
    if (fileDesc.state === "uploaded" /* UPLOADED */) {
      const consumption = this.getConsumptionData();
      if (consumption) {
        const usedSpace = consumption["currentValue"] !== 0 ? consumption["currentValue"] : 0;
        consumption["currentValue"] = usedSpace + fileDesc.size;
      }
    }
    const index = this.uploadingFileDescriptors.indexOf(fileDesc);
    if (index > -1) {
      this.uploadingFileDescriptors.splice(index, 1);
      this.uploadingFileDescriptorsSubject.next({ size: this.getUploadingFilesSize() });
    }
  }
  isEnoughAvailableSpaceForFiles(filesToSend) {
    if (!filesToSend.length) return true;
    let newFilesSize = 0;
    filesToSend.forEach((attachmentFile) => {
      if (!attachmentFile.fd) {
        if (attachmentFile.file) {
          newFilesSize += attachmentFile.file.size;
        } else if (attachmentFile.size) {
          newFilesSize += attachmentFile.size;
        }
      }
    });
    const consumption = this.getConsumptionData();
    const totalAvailableSpace = consumption["maxValue"];
    const usedSpace = consumption["currentValue"] !== 0 ? consumption["currentValue"] : 0;
    const remainingSpace = totalAvailableSpace - usedSpace;
    const filesUploadingSize = this.getUploadingFilesSize();
    this.logger.debug(`[FileStorageService] isEnoughAvailableSpaceForFiles - totalAvailableSpace: ${totalAvailableSpace} - usedSpace: ${usedSpace} - filesUploadingSize: ${filesUploadingSize}`);
    return newFilesSize < remainingSpace - filesUploadingSize;
  }
  isEnoughAvailableSpaceForFileDescriptor(fileId, fileViewers) {
    if (!fileId) {
      return true;
    }
    const fileDescriptor = this.getFileDescriptorById(fileId);
    const consumption = this.getConsumptionData();
    const totalAvailableSpace = consumption["maxValue"];
    const usedSpace = consumption["currentValue"] !== 0 ? consumption["currentValue"] : 0;
    const remainingSpace = totalAvailableSpace - usedSpace;
    const filesUploadingSize = this.getUploadingFilesSize();
    return fileDescriptor.size * fileViewers.length < remainingSpace - filesUploadingSize;
  }
  stopAllFileTransfer() {
    this.fileDescriptors.forEach((fileDesc) => {
      if (fileDesc) {
        if (fileDesc.abortTransferController) fileDesc.abortTransferController.abort();
        if (fileDesc.abortXMLHttpRequestArray?.length) {
          fileDesc.abortXMLHttpRequestArray.map((func) => {
            func();
          });
        }
      }
    });
  }
  getMimeInfo(mimeType) {
    let icon;
    let img = false;
    let commonType;
    const splitMime = mimeType.split("/");
    switch (splitMime[0]) {
      case "text":
        switch (splitMime[1]) {
          case "csv":
            icon = "txt-type";
            commonType = "csv";
            break;
          case "css":
          case "html":
            icon = "code-type";
            commonType = "code";
            break;
          default:
            icon = "txt-type";
            commonType = "txt";
            break;
        }
        break;
      case "image":
        switch (splitMime[1]) {
          case "svg+xml":
            icon = "image-type";
            commonType = "image";
            break;
          case "vnd.adobe.photoshop":
          case "photoshop":
          case "x-photoshop":
          case "psd":
            icon = "psd-type";
            commonType = "psd";
            break;
          default:
            icon = "image-type";
            img = true;
            commonType = "image";
            break;
        }
        break;
      case "audio":
        icon = "audio-type";
        commonType = "audio";
        break;
      case "video":
        icon = "video-type";
        commonType = "video";
        break;
      case "application":
        switch (splitMime[1]) {
          case "pdf":
            icon = "pdf-type";
            commonType = "pdf";
            break;
          case "msword":
          case "vnd.openxmlformats-officedocument.wordprocessingml.document":
            icon = "document-type";
            commonType = "document";
            break;
          case "vnd.ms-excel":
          case "vnd.openxmlformats-officedocument.spreadsheetml.sheet":
          case "vnd.openxmlformats-officedocument.spreadsheetml.template":
          case "vnd.ms-excel.sheet.macroEnabled.12":
            icon = "excel-type";
            commonType = "spreadsheet";
            break;
          case "vnd.ms-powerpoint":
          case "vnd.openxmlformats-officedocument.presentationml.presentation":
          case "vnd.openxmlformats-officedocument.presentationml.slideshow":
            icon = "powerpoint-type";
            commonType = "presentation";
            break;
          case "illustrator":
          case "postscript":
            icon = "ai-type";
            commonType = "ai";
            break;
          case "photoshop":
          case "psd":
            icon = "psd-type";
            commonType = "psd";
            break;
          case "javascript":
          case "json":
          case "typescript":
          case "xml":
            icon = "code-type";
            commonType = "code";
            break;
          case "zip":
          case "x-rar-compressed":
          case "x-7z-compressed":
          case "x-tar":
            icon = "archive-type";
            commonType = "archive";
            break;
          default:
            icon = "unknown-type";
            commonType = "unknown";
            break;
        }
        break;
      default:
        icon = "unknown-type";
        commonType = "unknown";
        break;
    }
    return { icon: `assets/svg_dist/sprite.svg#${icon}`, img, commonType };
  }
  /* RECORDING FILES MANAGEMENT */
