  getSharedWithMeConferenceRecordingFiles() {
    this.sharedWithMeConferenceRecordingFilesSubject.next(this.sharedWithMeConferenceRecordingFiles);
    return this.sharedWithMeConferenceRecordingFiles;
  }
  getConferenceRecordingFileById(fileId) {
    let result;
    this.conferenceRecordingFileDescriptors.forEach((fileDescriptor) => {
      if (fileDescriptor && fileDescriptor.id === fileId) {
        result = fileDescriptor;
      }
    });
    if (!result) {
      this.conferenceRecordingFiles.forEach((recordingFile) => {
        if (recordingFile.associatedRecordingFiles) {
          recordingFile.associatedRecordingFiles.forEach((fileDescriptor) => {
            if (fileDescriptor && fileDescriptor.id === fileId) {
              result = fileDescriptor;
            }
          });
        }
      });
    }
    if (!result) {
      this.sharedWithMeConferenceRecordingFiles.forEach((fileDescriptor) => {
        if (fileDescriptor && fileDescriptor.id === fileId) {
          result = fileDescriptor;
        }
      });
    }
    return result;
  }
  async getSharedWithMeConferenceRecordingFilesFromServer() {
    try {
      const url = `${this.portalURL}/viewers/${this.contactService.userContact.dbId}?format=full&purpose=conference_record&typeMIME=video&sortField=uploadedDate&sortOrder=-1`;
      const headers = this.authService.getRequestHeader();
      const response = await fetch(url, { method: "GET", headers });
      if (!response.ok) {
        throw response;
      }
      const recordingFileDescriptorsResponse = await response.json();
      const recordingFileDescriptorsData = recordingFileDescriptorsResponse.data;
      if (!recordingFileDescriptorsData) {
        throw recordingFileDescriptorsData;
      }
      const receivedFileDescriptors = recordingFileDescriptorsData.map((fileDescriptorData) => {
        return this.createFileDescriptorFromData(fileDescriptorData);
      });
      if (receivedFileDescriptors.length) {
        receivedFileDescriptors.forEach((fd) => {
          if (!this.sharedWithMeConferenceRecordingFiles.find((_fileDescriptor) => {
            return _fileDescriptor.id === fd.id;
          })) {
            this.sharedWithMeConferenceRecordingFiles.unshift(fd);
          }
        });
      }
      this.sharedWithMeConferenceRecordingFilesSubject.next(this.sharedWithMeConferenceRecordingFiles);
      this.logger.info("[FileStorageService] getSharedWithMeConferenceRecordingFiles -- success");
      return this.sharedWithMeConferenceRecordingFiles;
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "getSharedWithMeConferenceRecordingFiles");
      this.logger.error(`[fileStorageService] ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
  async deleteConferenceRecordingFile(conferenceRecordingFileId) {
    try {
      this.logger.info("[FileStorageService] deleteConferenceRecordingFile");
      const url = `${config.restServerUrl}/api/rainbow/filestorage/v1.0/conferences-recordings/${conferenceRecordingFileId}`;
      const headers = this.authService.getRequestHeader();
      const response = await fetch(url, { method: "DELETE", headers });
      if (!response.ok) {
        throw response;
      }
      const conferenceFileResponse = await response.json();
      const deletedConferenceFile = conferenceFileResponse.data;
      if (!deletedConferenceFile) {
        throw response;
      }
      this.logger.info("[FileStorageService] deleteConferenceRecordingFile -- success");
      const filteredConferenceRecordingFiles = this.conferenceRecordingFiles.filter((recordingFile) => {
        return recordingFile.id !== deletedConferenceFile.id;
      });
      this.conferenceRecordingFiles = filteredConferenceRecordingFiles;
      this.conferenceRecordingFilesSubject.next(this.conferenceRecordingFiles);
      await this.retrieveUserConsumption();
      return this.conferenceRecordingFiles;
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "deleteConferenceRecordingFile");
      this.logger.error(`[fileStorageService] ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
  async getConferenceRecordingAssociatedFiles(conferenceRecordingFile) {
    try {
      this.logger.info("[FileStorageService] getConferenceRecordingAssociatedFiles");
      const result = [];
      if (!conferenceRecordingFile.associatedRecordingFiles) {
        this.logger.info("[FileStorageService] getConferenceRecordingAssociatedFiles - fetching from the server");
        conferenceRecordingFile.associatedRecordingFiles = [];
        for (let i = 0; i < conferenceRecordingFile.records.length; i++) {
          let fileDescriptor = this.getFileDescriptorById(conferenceRecordingFile.records[i].fileId);
          if (!fileDescriptor) {
            fileDescriptor = await this.retrieveOneFileDescriptor(conferenceRecordingFile.records[i].fileId);
          }
          this.logger.info("[FileStorageService] getConferenceRecordingAssociatedFiles -- success: " + conferenceRecordingFile.records[i].fileName);
          result.push(fileDescriptor);
        }
        conferenceRecordingFile.associatedRecordingFiles = result;
        return result;
      }
      this.logger.info("[FileStorageService] getConferenceRecordingAssociatedFiles - return results from cache");
      return conferenceRecordingFile.associatedRecordingFiles;
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "getConferenceRecordingAssociatedFiles");
      this.logger.error(`[fileStorageService] ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
