      const url = `${this.portalURL}rooms/lobbies`;
      const headers = this.authService.getRequestHeader();
      const response = await fetch(url, { method: "GET", headers });
      if (!response.ok) {
        throw response;
      }
      const responseData = await response.json();
      this.logger.info(`[bubbleService] getMyLobbyListsAsUser - success`);
      const data = responseData.data;
      const promisesList = [];
      data.forEach((element) => {
        if (element) {
          const bubbleInfos = { dbId: element.id, additionDate: element.additionDate };
          promisesList.push(this.addConnectedUserToWaitingListForBubble(bubbleInfos, "pending" /* PENDING */, element.name));
        }
      });
      await allSettled_default(promisesList);
      this.sendEvent("ON_MY_USER_REQUESTS_TO_JOIN_BUBBLE_CHANGE" /* ON_MY_USER_REQUESTS_TO_JOIN_BUBBLE_CHANGE */);
