  /**
   * Get the bubble settings
   * @param bubble - The bubble
   */
  getBubbleSettings(bubble) {
    const settings = {};
    const bubbleRB = bubble;
    settings.name = bubble.name;
    settings.description = bubble.description;
    settings.autoRegister = bubble.autoRegister ? bubble.autoRegister : "unlock";
    settings.autoAcceptInvitation = bubble.autoAcceptInvitation;
    settings.muteUponEntry = bubbleRB.conference ? bubbleRB.conference.muteUponEntry : "false";
    settings.playEntryTone = bubbleRB.conference ? bubbleRB.conference.playEntryTone : "true";
    settings.includeAllPhoneNumbers = bubbleRB.conference ? bubbleRB.conference.includeAllPhoneNumbers : false;
    settings.contentToAutoClear = bubbleRB.conference ? bubbleRB.conference.contentToAutoClear : {
      im: false,
      poll: false,
      document: false,
      member: false
    };
    return settings;
  }
