  /*
      MANAGE OPEN INVITE UPDATES FOR BUBBLES
  */
  onRoomOpeninviteUpdates(openinviteElem) {
    try {
      if (openinviteElem.length > 0) {
        this.logger.info("[bubbleService] onRoomOpeninviteUpdates -- openinvite");
        const openInviteAction = openinviteElem.attr("action");
        const roomId = openinviteElem.find("roomid").text();
        const openInviteId = openinviteElem.find("openinviteid").text();
        const roomType = openinviteElem.find("roomType").text();
        const invitationURL = openinviteElem.find("invitationURL").text();
        switch (openInviteAction) {
          case "update":
            Object.keys(this.openInviteIdByRoomId).forEach((key) => {
              if (this.openInviteIdByRoomId[key] && this.openInviteIdByRoomId[key].openInviteId !== openInviteId && key === roomId) {
                this.logger.info("[bubbleService] onRoomOpeninviteUpdates -- openinviteId updated for " + key);
                this.openInviteIdByRoomId[key].openInviteId = openInviteId;
                this.openInviteIdByRoomId[key].openInviteLink = invitationURL;
                this.openInviteIdByRoomIdSubject.next({
                  invitationURL,
                  openInviteId,
                  roomType,
                  id: roomId,
                  action: `updated`
                });
              }
            });
            break;
          case "create":
            if (roomId && openInviteId) {
              this.openInviteIdByRoomId[roomId] = {};
              this.openInviteIdByRoomId[roomId].roomType = roomType;
              this.openInviteIdByRoomId[roomId].openInviteId = openInviteId;
              this.openInviteIdByRoomId[roomId].openInviteLink = invitationURL;
              this.openInviteIdByRoomIdSubject.next({
                invitationURL,
                openInviteId,
                roomType,
                id: roomId,
                action: `updated`
              });
              this.logger.info("[bubbleService] onRoomOpeninviteUpdates -- openinviteId " + openInviteId + " assigned to room " + roomId);
              this.eventService.publish("ON_OPEN_INVITE_ID_UPDATED_EVENT", this.bubbles[roomId]);
            }
            break;
          case "delete":
            Object.keys(this.openInviteIdByRoomId).forEach((key) => {
              if (this.openInviteIdByRoomId[key] && this.openInviteIdByRoomId[key].openInviteId === openInviteId && key === roomId) {
                this.logger.info("[bubbleService] onRoomOpeninviteUpdates -- openinviteId removed from " + key);
                delete this.openInviteIdByRoomId[key];
                this.openInviteIdByRoomIdSubject.next({
                  invitationURL,
                  openInviteId,
                  roomType,
                  id: roomId,
                  action: `deleted`
                });
                this.eventService.publish("ON_OPEN_INVITE_ID_DELETED_EVENT", this.bubbles[roomId]);
              }
            });
            break;
          default:
            this.logger.info("[bubbleService] onRoomOpeninviteUpdates -- openinviteId - unkown action : " + openInviteAction);
            break;
        }
      }
    } catch (error) {
      this.logger.error(`[bubbleService] onRoomOpeninviteUpdates -- openinviteId - error : ${error}`);
    }
  }
