  onBubblePresence(stanza) {
    try {
      const stanzaElem = xmlParser_default(stanza);
      const fromJid = stanzaElem.attr("from");
      const fromRoomBareJid = this.xmppService.getBareJidFromJid(fromJid);
      let fromUserJid = this.xmppService.getResourceFromJid(fromJid);
      const statusElems = stanzaElem.find("status");
      let statusCode = null;
      statusElems.forEach((statusElem) => {
        const code2 = statusElem.attr("code");
        if (code2 === "332") {
          statusCode = "332";
        }
        if (code2 === "338") {
          statusCode = "338";
        }
        if (code2 === "339") {
          statusCode = "339";
        }
        if (code2 === "110" && !statusCode) {
          statusCode = "110";
        }
      });
      const room = this.getBubbleFromCache(fromRoomBareJid);
      if (room) {
        if (statusCode === "338") {
          this.logger.info("[bubbleService] onBubblePresence - " + room.dbId + "- Deactivated");
          room.isActive = false;
          room.rxSubject.next(RBEvent.create("isActive"));
        } else if (statusCode === "339") {
          this.logger.info("[bubbleService] onBubblePresence - " + room.dbId + "- Reactivated");
          room.ready = false;
          this.sendInitialRoomPresenceSync(room);
          room.isActive = true;
          room.rxSubject.next(RBEvent.create("isActive"));
        } else {
          this.logger.info("[bubbleService] onBubblePresence -- " + room.dbId);
          if (fromUserJid.indexOf("/") !== -1) {
            fromUserJid = this.xmppService.getBareJidFromJid(fromUserJid);
          }
          if (this.contactService.isUserContactJid(fromUserJid)) {
            const type = stanzaElem.attr("type");
            if (type && type === "unavailable" && statusCode === "110") {
              this.logger.warn("[bubbleService] disconnected from room " + room.getNameForLogs() + " because of a unavailable presence -- do nothing");
            } else if (statusCode === "332") {
              this.logger.warn("[bubbleService] disconnected from room " + room.getNameForLogs() + " because of a system shutdown");
              room.ready = false;
              this.sendInitialRoomPresenceSync(room);
            } else {
              room.ready = true;
              if (this.roomPresenceWaitingList?.length) {
                this.roomPresenceWaitingList.forEach((waitingListRoom, index) => {
                  if (waitingListRoom.dbId === room.dbId) {
                    this.roomPresenceWaitingList.splice(index, 1);
                  }
                });
              }
              if (room.initPresPromise) {
                this.logger.info("[bubbleService] onBubblePresence - initPresPromise resolved");
                room.initPresPromiseResolve(room);
                if (room.initPresInterval) {
                  room.initPresInterval.unsubscribe();
                  room.initPresInterval = null;
                }
                room.initPresPromise = null;
                room.initPresPromiseResolve = null;
              }
            }
          } else if (room.dbId && !this.bubbles[room.dbId]) {
            this.getServerBubble(room.dbId);
          }
        }
      }
      return true;
    } catch (error) {
      this.logger.error("[bubbleService] onBubblePresence error " + error);
      return true;
    }
  }
