  updateUserStatus(bubble, bubbleUser, status2) {
    let actionEvent = this.getEventFromBubbleStatus(status2);
    ;
    if (this.contactService.isUserContactJid(bubbleUser.user.jid)) {
      this.logger.info("[bubbleService] Connected User status " + status2);
      switch (status2) {
        case "deleted":
          bubbleUser.status = "deleted" /* DELETED */;
          delete this.bubblesByJids[bubble.jid];
          delete this.bubbles[bubble.dbId];
          this.logger.info("[bubbleService] updateUserStatus --deleteRoom successfully (" + bubble.dbId + ")");
          this.sendUnavailableRoomPresence(bubble);
          this.fileStorageService?.removeRoomFileViewer(bubble);
          if (this.contactService.userContact.guestMode && !bubble.isWebinarBubble()) {
            this.eventService.publish("ON_OPEN_POPUP", "concludeInvitation");
          }
          if (bubble.isBubbleConferenceStarted()) {
            const activeConference = this.webConferenceService?.getWebConferenceSessionById(bubble.dbId);
            if (activeConference?.haveJoined) {
              this.webConferenceService?.leaveWebConference(activeConference);
            }
            this.webConferenceService?.sendWebConferenceEvent("ON_CONFERENCE_ENDED" /* ON_CONFERENCE_ENDED */, bubble);
          }
          break;
        case "unsubscribed":
          this.logger.info("[bubbleService] unsubscribed successfully (" + bubble.dbId + ")");
          this.sendUnavailableRoomPresence(bubble);
          bubbleUser.status = "unsubscribed" /* UNSUBSCRIBED */;
          bubble.updateAvatarInfo();
          bubble.ready = false;
          break;
        case "accepted":
          bubbleUser.status = "accepted" /* ACCEPTED */;
          this.updateMyUserToAcceptedStatus(bubble, true);
          actionEvent = void 0;
          break;
        case "rejected":
          delete this.bubblesByJids[bubble.jid];
          delete this.bubbles[bubble.dbId];
          bubbleUser.status = "rejected" /* REJECTED */;
          break;
        default:
          break;
      }
      if (actionEvent) {
        this.sendEvent(actionEvent, { bubble, bubbleUser });
      }
    } else {
      this.logger.info(`[bubbleService] Update user ${bubbleUser.user.dbId} with status ${status2}`);
      if (bubbleUser.status === "deleted" /* DELETED */ && status2 === "accepted" /* ACCEPTED */) {
        bubbleUser.date = /* @__PURE__ */ new Date();
        if (bubbleUser.role === "moderator" /* ORGANIZER */) {
          bubbleUser.role = "user" /* USER */;
        }
      }
      bubbleUser.status = status2;
      bubble.updateAvatarInfo();
      this.refreshMemberAndOrganizerLists(bubble);
      switch (status2) {
        case "invited":
          bubble.nbParticipants += 1;
          actionEvent = void 0;
          break;
        case "accepted":
          break;
        case "rejected":
          bubble.nbParticipants -= 1;
          break;
        case "deleted":
          bubble.nbParticipants -= 1;
          break;
        case "unsubscribed":
          bubble.nbParticipants -= 1;
          break;
        default:
          break;
      }
      if (actionEvent) {
        const bubbleActionEvent = this.convertToBubbleEvents(actionEvent);
        bubble.sendEvent(bubbleActionEvent, bubbleUser);
        this.sendEvent(actionEvent, { bubble, bubbleUser });
      }
    }
  }
