  async startWebConference(bubble) {
    if (!bubble) {
      throw Error("Wrong or missing parameters");
    }
    if (!this.profileService.isFeatureEnabled(this.profileService.FeaturesEnum.WEBRTC_CONFERENCE_ALLOWED)) {
      throw Error("[WebConferenceService] startWebConference -- User does not have the profile feature WEBRTC_CONFERENCE_ALLOWED");
    }
    try {
      this.logger.debug("[WebConferenceService] startWebConference -- " + bubble.dbId);
      let webConferenceSession = this.webConferenceSessions[bubble.dbId];
      if (!webConferenceSession) {
        webConferenceSession = new WebConferenceSession(bubble.dbId, bubble);
        this.webConferenceSessions[bubble.dbId] = webConferenceSession;
      }
      if (!webConferenceSession.localParticipant) {
        webConferenceSession.localParticipant = BubbleConferenceParticipant.create(this.contactService.userContact.dbId);
        webConferenceSession.localParticipant.contact = this.contactService.userContact;
      }
      webConferenceSession.isMyConference = true;
      webConferenceSession.haveJoined = true;
      if (webConferenceSession.status !== "connecting" /* CONNECTING */) {
        webConferenceSession.status = "connecting" /* CONNECTING */;
        this.sendEvent("ON_CONFERENCE_STATUS_UPDATE" /* ON_CONFERENCE_STATUS_UPDATE */, { bubbleConference: webConferenceSession, status: "connecting" /* CONNECTING */ });
      }
      const params = {};
      if (this.profileService.isFeatureEnabled(this.profileService.FeaturesEnum.WEBRTC_GRID49) || this.settingsService.getBooleanSetting("grid49")) {
        this.logger.info("[WebConferenceService] startWebConference -- activate grid 49");
        params.services = ["video-compositor"];
      }
      const body = JSON.stringify(params);
      const url = `${config.restServerUrl}/api/rainbow/conference/v1.0/rooms/${bubble.dbId}/start`;
      const headers = this.authService.getPostHeader();
      const response = await fetch(url, { method: "POST", headers, body });
      if (!response.ok) throw response;
      this.logger.info("[WebConferenceService] startWebConference -- successfully");
    } catch (error) {
      this.resetBusyStateIfNeeded();
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "startWebConference");
      this.logger.error(`[WebConferenceService] -- ${errorInfo.message}`);
      const data = {
        popupTitle: "unableToJoin",
        popupBody: "joinMeetingFailure",
        okLabel: "ok"
      };
      delete this.webConferenceSessions[bubble.dbId];
      this.mainService.showGlobalPopupMessage(data);
      throw errorInfo.error;
    }
    return this.joinWebConference(bubble);
  }
