  /**
   * Make the jingle webtc call with sharing and audio towards the destination in the call
   * @param call - The Call object
   */
  async makeJingleSharingCall(call) {
    try {
      this.logger.info("[webrtcP2PService] MEDIA   | makeJingleSharingCall - make desktop sharing call");
      let type = "sharing";
      if (call.localMedia === CallMedia.SHARING) {
        type = "sharing-only";
      }
      await this.webrtcConfigAndUtils.setWebrtcConfiguration();
      this.logger.info("[webrtcP2PService] SHARING | getUserMedia success");
      const mediaPillarSessionsLocalStreams = [];
      const mediaPillarAudioCalls = this.getMediaPillarAudioCalls();
      mediaPillarAudioCalls.forEach((mediaPillarAudioCall) => {
        const mediaPillarSession = this.xmppService.connection.jingle.sessions[mediaPillarAudioCall.id];
        const mediaPillarStreams = mediaPillarSession ? mediaPillarSession.localStreams : null;
        if (mediaPillarStreams) {
          mediaPillarSessionsLocalStreams.push.apply(mediaPillarSessionsLocalStreams, mediaPillarStreams);
        }
      });
      const callStreamsForSharingCall = !mediaPillarAudioCalls || mediaPillarAudioCalls.length === 0 ? call.localStreams : call.localStreams.filter(function(localStream) {
        return !mediaPillarSessionsLocalStreams?.includes(localStream);
      });
      this.xmppService.connection.jingle.initiate(call.fullJid, this.xmppService.connection.jid, type, callStreamsForSharingCall, call.id);
      call.setStatus("CONNECTING" /* CONNECTING */);
      this.sendUpdateCallEvent(call);
    } catch (error) {
      this.makingCall = false;
      if (call) {
        this.removeCallObject(call);
      }
      this.resetToSafeState(call);
      this.logger.info("[webrtcP2PService] MEDIA   | makeJingleSharingCall failure : " + JSON.stringify({ error: error.message }));
    }
  }
