    if (!webrtcDeviceId) {
      this.logger.info("[TelephonyServiceSipWise] setRingingDevice : Anomaly no webrtc device");
      return null;
    }
    destinations.push(webrtcDeviceId);
    const officePhoneDeviceId = this.getDeviceWithType("sip")?.deviceId;
    if (officePhoneDeviceId && ringingDeviceId === officePhoneDeviceId) {
      destinations.push(officePhoneDeviceId);
    }
    return destinations;
