  /**
   * getUserGroups
   */
  async getUserGroups() {
    try {
      this.logger.info("[TelephonyServiceSipWise] getUserGroups");
      const url = new URL(this.portalURL + "groups");
      url.searchParams.set("limit", String(100));
      const headers = this.authService.getRequestHeader();
      this.logger.info("[TelephonyServiceSipWise] groups GET " + url);
      const response = await fetch(url.toString(), { method: "GET", headers });
      if (!response.ok) {
        throw response;
      }
      const responseBody = await response.json();
      const respData = responseBody.data;
      this.logger.info("[TelephonyServiceSipWise] getUserGroups success / status : " + response.statusText);
      this.telephonyService.sipWiseUserGroupsDataClear();
      if (respData.length > 0) {
        this.telephonyService.sipWiseUserGroupsData.myMemberId = this.contactService.userContact.dbId;
        respData.forEach((group) => {
          this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.push(group);
          const mngAssistAsHG = group.type === "hunting_group" && group.subType === "manager_assistant";
          if (group.type === "hunting_group" && !mngAssistAsHG || // default hunting-group or attendant hunting-group
          group.type === "call_queue") {
            this.telephonyService.sipWiseUserGroupsData.huntingGroupNb++;
          }
          if (mngAssistAsHG) {
            this.telephonyService.sipWiseUserGroupsData.isSomeMngAssistAsHG = true;
            const onlyManager = group.members.find((elt) => elt.roles[0] === "leader");
            if (onlyManager) {
              if (group.members[0].memberId === this.contactService.userContact.dbId) {
                group.members.forEach((member) => {
                  if (member.roles[0] === "assistant") {
                    this.telephonyService.sipWiseUserGroupsData.managerAssistantMyAssistList.push({ id: member.memberId, status: member.status });
                  }
                });
              } else {
                this.telephonyService.sipWiseUserGroupsData.managerAssistantMyMngList.push({ id: group.members[0].memberId, status: group.members[0].status });
              }
            } else {
              this.logger.info("[TelephonyServiceSipWise] getUserGroups for groupId : " + group.id + " Anomaly not 1 only manager in 1st pos");
            }
          } else if (group.type === "manager_assistant") {
            this.telephonyService.sipWiseUserGroupsData.managerAssistantNb++;
            if (this.telephonyService.sipWiseUserGroupsData.managerAssistantNb === 1) {
              const onlyManager = group.members.find((elt) => elt.roles[0] === "manager");
              if (onlyManager) {
                this.telephonyService.sipWiseUserGroupsData.managerAssistGrId = group.id;
                this.telephonyService.sipWiseUserGroupsData.managerId = onlyManager.memberId;
                this.telephonyService.sipWiseUserGroupsData.managerName = onlyManager.displayName;
                this.telephonyService.sipWiseUserGroupsData.managerStatus = onlyManager.status;
              } else {
                this.logger.info("[TelephonyServiceSipWise] getUserGroups for groupId : " + group.id + " Anomaly not 1 only manager");
              }
              const onlyAssistant = group.members.find((elt) => elt.roles[0] === "assistant");
              if (onlyAssistant) {
                this.telephonyService.sipWiseUserGroupsData.assistantId = onlyAssistant.memberId;
                this.telephonyService.sipWiseUserGroupsData.assistantName = onlyAssistant.displayName;
                this.telephonyService.sipWiseUserGroupsData.assistantStatus = onlyAssistant.status;
              } else {
                this.logger.info("[TelephonyServiceSipWise] getUserGroups for groupId : " + group.id + " Anomaly not 1 only assistant");
              }
            } else {
              this.logger.info("[TelephonyServiceSipWise] getUserGroups : Anomaly not a 1:1 mng/ass situation");
            }
          }
        });
      }
      if (this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.length >= 1) {
        this.logger.info("[TelephonyServiceSipWise] getUserGroups  : " + this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.length + " user's group(s)");
      } else {
        this.logger.info("[TelephonyServiceSipWise] getUserGroups  : no group");
      }
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "getUserGroups");
      this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
  /**
   * joinGroup
   * @param {string} groupId group identifier
   * @param {string} leaderId leader identifier (for mng-assist GR)
   */
  async joinGroup(groupId, leaderId = void 0) {
    try {
      this.logger.info("[TelephonyServiceSipWise] joinGroup for groupId : " + groupId + " leaderId:" + leaderId);
      let wrongParaMsg = "";
      let indexGroup = -1;
      if (groupId) {
        if (this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.length === 0) {
          wrongParaMsg = "no group";
        } else {
          indexGroup = this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.findIndex((elt) => elt.id === groupId);
          if (indexGroup === -1) {
            wrongParaMsg = "group not found";
          }
        }
      } else {
        wrongParaMsg = "missing groupId";
      }
      if (leaderId) {
        const found = this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.find(
          (group) => (
            // eslint-disable-next-line @typescript-eslint/indent
            group.type === "hunting_group" && group.subType === "manager_assistant" && group.members[0].memberId === leaderId
          )
        );
        if (!found) {
          const errorMessage = "sipwise joinGroup -- invalid leaderId";
          this.logger.error("[telephonyService] " + errorMessage);
          return;
        }
      }
      if (wrongParaMsg !== "") {
        const error = new Error("join group failure - " + wrongParaMsg);
        this.logger.error("[TelephonyServiceSipWise] join group anomaly:" + wrongParaMsg);
        throw error;
      }
      let urlQueryParams = "";
      if (leaderId) {
        urlQueryParams = "?leaderId=" + leaderId;
      }
      const url = new URL(this.portalURL + "groups/" + encodeURIComponent(groupId) + "/join" + urlQueryParams);
      const headers = this.authService.getPostHeader();
      this.logger.info("[TelephonyServiceSipWise] joinGroup POST " + url);
      const response = await fetch(url.toString(), { method: "POST", headers });
      if (!response.ok) {
        throw response;
      }
      const responseBody = await response.json();
      const respData = responseBody.data;
      this.logger.info("[TelephonyServiceSipWise] joinGroup success / status : " + response.statusText);
      indexGroup = this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.findIndex((elt) => elt.id === respData.id);
      if (indexGroup !== -1) {
        this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.splice(indexGroup, 1, respData);
      } else {
        this.logger.info("[TelephonyServiceSipWise] joinGroup  : anomaly group not present in local struct");
      }
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "joinGroup");
      this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
