  /**
   * joinAllGroups
   *  @param {string} subType group sub type (to target HG groups or mngAssist groups)
   */
  async joinAllGroups(subType = "default") {
    try {
      this.logger.info("[TelephonyServiceSipWise] joinAllGroups");
      let wrongParaMsg = "";
      if (this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.length === 0) {
        wrongParaMsg = "no group";
      }
      if (subType !== "default" && subType !== "manager_assistant" && subType !== "hg_attendant") {
        wrongParaMsg = "wrong group subType";
      }
      if (wrongParaMsg !== "") {
        const error = new Error("joinAllGroups failure - " + wrongParaMsg);
        this.logger.error("[TelephonyServiceSipWise] join all groups anomaly:" + wrongParaMsg);
        throw error;
      }
      let urlQueryParams = "";
      if (subType !== "default") {
        urlQueryParams = "?subType=" + subType;
      }
      const url = new URL(this.portalURL + "groups/join" + urlQueryParams);
      const headers = this.authService.getPostHeader();
      this.logger.info("[TelephonyServiceSipWise] joinAllGroups POST " + url);
      const response = await fetch(url.toString(), { method: "POST", headers });
      if (!response.ok) {
        throw response;
      }
      const responseBody = await response.json();
      const respData = responseBody.data;
      this.logger.info("[TelephonyServiceSipWise] joinAllGroups success / status : " + response.statusText);
      respData.forEach((group) => {
        const indexGroup = this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.findIndex((elt) => elt.id === group.id);
        if (indexGroup !== -1) {
          this.telephonyService.sipWiseUserGroupsData.sipWiseUserGroupsList.splice(indexGroup, 1, group);
        } else {
          this.logger.info("[TelephonyServiceSipWise] joinAllGroups  : anomaly group not present in local struct");
        }
      });
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "joinAllGroups");
      this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
