  /**
   * changeMemberRole
   * @param {string} groupId group identifier
   * @param {string} memberId member identifier
   * @param {boolean} isAgent
   * @param {boolean} isManager
   */
  async changeMemberRole(groupId, memberId, isAgent, isManager) {
    try {
      this.logger.info("[TelephonyServiceSipWise] changeMemberRole - groupId: " + groupId + " - memberId: " + memberId + " - isAgent: " + isAgent.toString() + " - isManager: " + isManager.toString());
      const roles = [];
      const url = new URL(this.portalURL + "groups/" + encodeURIComponent(groupId) + "/members/" + encodeURIComponent(memberId));
      const headers = this.authService.getPostHeader();
      if (isAgent) {
        roles.push("agent");
      }
      if (isManager) {
        roles.push("manager");
      }
      const reqData = {
        roles
      };
      const body = JSON.stringify(reqData);
      const response = await fetch(url.toString(), { method: "PUT", headers, body });
      if (!response.ok) {
        throw response;
      }
      this.logger.info("[TelephonyServiceSipWise] DemoteMemberToAgent success / status : " + response.statusText);
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "DemoteMemberToAgent");
      this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
