  /**
   * searchHuntingGroups
   * @param {string} searchText searched group name
   * @param {number} limit max number of results
   */
  async searchHuntingGroups(searchText, limit = 20) {
    try {
      this.logger.info("[TelephonyServiceSipWise] searchHuntingGroups: " + searchText);
      if (!this.telephonyService || !this.telephonyService.isSipWise()) {
        this.logger.debug(`[TelephonyServiceSipWise] searchHuntingGroups -- Request ignored as SipWise telephony not running`);
        return [];
      }
      const url = new URL(this.portalURL + "search/huntinggroups");
      url.searchParams.set("name", searchText);
      const headers = this.authService.getRequestHeader();
      this.logger.info("[TelephonyServiceSipWise] getUserGroupForwards GET " + url);
      const response = await fetch(url.toString(), { method: "GET", headers });
      if (!response.ok) {
        throw response;
      }
      const responseBody = await response.json();
      const respData = responseBody.data;
      this.logger.info("[TelephonyServiceSipWise] searchHuntingGroups success");
      const huntingGroups = respData.map((huntingGroup) => {
        const contact = this.contactService.createBasicContact(null, huntingGroup.shortNumber, false);
        contact.updateName(null, huntingGroup.name);
        contact.phoneInternalNumber = huntingGroup.shortNumber;
        contact.phonePersoCan = huntingGroup.externalNumber ? huntingGroup.externalNumber : "";
        contact.dbId = huntingGroup.id;
        contact.createAvatar();
        return contact;
      });
      huntingGroups.splice(limit);
      return huntingGroups;
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "searchHuntingGroups");
      this.logger.error(`[TelephonyServiceSipWise] ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
