  // Management of personal contacts Get & Search
  // --------------------------------------------
  /**
   * Method getPersonalContacts
   * @description This API allows users to retrieve the list of the personal directory contacts of the user with full information pour each of them
   * (API request to {@link https://api.openrainbow.org/directory/#api-directory-GetDirectoryList Rainbow Company Directory portal - directory - Get a list of directory entries data})
   * @memberof PersonalDirectoryService
   * @public
   * @param {string} [format] Allows to retrieve more or less contact details in response.
   *      - small: id, directoryType, firstName, lastName
   *      - medium: id, directoryType, firstName, lastName, workPhoneNumbers
   *      - full: all fields.
   * @returns {Promise<{ contacts: DirectoryContact[]; limit: number; offset: number; total: number }>} object contaning result of search with
   * {
   *   contacts :  {array}     // Found personal directory contacts
   *   limit :     {number}    // Limit specified at the search request, fix in our case by default to max possible.
   *   offset :    {number}    // The position of first retrieved contact entry
   *   total :     {number}    // Total number of available personal directory contacts (May be different from the number of returned contacts)
   * }
   */
  async getPersonalContacts(format2 = "full") {
    try {
      if (!this.personalDirectoryEnabled)
        throw Error("[PersonalDirectoryService] getPersonalContacts -- User does not have the profile feature PERSONAL_DIRECTORY");
      const directoryScope = "personal";
      const entryType = "all";
      const limitForAll = 1e3;
      const url = `${this.directoryPortalURL}/entries?view=${directoryScope}&type=${entryType}&limit=${limitForAll}&format=${format2}`;
      const headers = this.authService.getRequestHeader();
      const response = await fetch(url, { method: "GET", headers });
      if (!response.ok) {
        throw response;
      }
      const responseData = await response.json();
      this.logger.info(`[PersonalDirectoryService] getPersonalContacts success -- Found ${responseData.total} contact(s)`);
      const contactsData = responseData.data;
      const persDirContacts = [];
      contactsData.forEach((contactData) => {
        const persDirContact = DirectoryContact.createFromData(contactData);
        this.createOrUpdateContact(persDirContact);
        persDirContacts.push(persDirContact);
      });
      return { contacts: persDirContacts, limit: responseData.limit, offset: responseData.offset, total: responseData.total };
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "getPersonalContacts");
      this.logger.error(`[PersonalDirectoryService] getPersonalContacts failure: ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
  /**
   * Method getPersonalContactsByCriteria
   * @description This API allows users to get a list of personal directory contacts data by optionally specifying
   * - Data format
   * - Pagination criteria (offset, limit)
   * - Search criteria (mode, pattern)
   * (API request to {@link https://api.openrainbow.org/directory/#api-directory-GetDirectoryList Rainbow Company Directory portal - directory - Get a list of directory entries data})
   * @memberof PersonalDirectoryService
   * @public
   * @param {object} [options] Search filter and criteria specified via the Option object
   * @property {string} options Option object that may contain the following properties:
   * @property {string} [options.format='full'] Allows to retrieve more or less contact details in response.
   *      - small: id, directoryType, firstName, lastName
   *      - medium: id, directoryType, firstName, lastName, workPhoneNumbers
   *      - full: all fields.
   * @property {number} [options.limit] Allows to specify the number personal directory contacts to retrieve.
   * Default value: 100
   * @property {number} [options.offset] Allows to specify the position of first personal directory contact to retrieve
   * If not specified, the search begins at the beginning, from the the first personal directory contact.
   * Warning: if offset > total, no results are returned.
   * @property {string} [options.searchBy] Allows to filter the list of directory entries on phone number or on the name provided in this option.
   * @property {string} [options.searchPattern] Allows to filter the list of directory entries by the words provided in this option
   * @returns {Promise<{ contacts: DirectoryContact[]; limit: number; offset: number; total: number }>} object contaning result of search with
   * {
   *   contacts :  {array}     // Found personal directory contacts
   *   limit :     {number}    // Limit specified at the search request
   *   offset :    {number}    // The position of first retrieved contact entry
   *   total :     {number}    // Total number of available personal directory contacts (May be different from the number of returned contacts)
   * }
   */
  async getPersonalContactsByCriteria(options = null) {
    try {
      const urlOptions = {};
      if (!this.personalDirectoryEnabled)
        throw Error("[PersonalDirectoryService] getPersonalContactsByCriteria -- User does not have the profile feature PERSONAL_DIRECTORY");
      if (options) {
        if (options.format && typeof options.format === "string" && options.format.length) {
          urlOptions.format = options.format;
        } else {
          urlOptions.format = "full";
        }
        if (options.limit) {
          urlOptions.limit = options.limit;
        }
        if (options.offset) {
          urlOptions.offset = options.offset;
        }
        if (options.searchPattern) {
          switch (options.searchBy) {
            case "phoneNumbers":
              urlOptions.phoneNumbers = encodeURIComponent(options.searchPattern);
              break;
            // case "tags":
            //     urlOptions.searchBy = encodeURIComponent(options.searchPattern);
            //     break;
            case "name":
            // Allows to filter the list of directory entries of user type on the name
            default:
              urlOptions.name = encodeURIComponent(options.searchPattern);
              break;
          }
        }
      } else {
        urlOptions.format = "full";
      }
      const directoryScope = "personal";
      const url = new URL(`${this.directoryPortalURL}/entries?view=${directoryScope}`);
      const urlParams = new URLSearchParams(urlOptions).toString();
      url.search = urlParams;
      const headers = this.authService.getRequestHeader();
      const response = await fetch(url.toString(), { method: "GET", headers });
      if (!response.ok) {
        throw response;
      }
      const responseData = await response.json();
      this.logger.info(`[PersonalDirectoryService] getPersonalContactsByCriteria success -- Found ${responseData.total} contact(s)`);
      const contactsData = responseData.data;
      const persDirContacts = [];
      contactsData.forEach((contactData) => {
        const persDirContact = DirectoryContact.createFromData(contactData);
        this.createOrUpdateContact(persDirContact);
        persDirContacts.push(persDirContact);
      });
      return { contacts: persDirContacts, limit: responseData.limit, offset: responseData.offset, total: responseData.total };
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "getPersonalContactsByCriteria");
      this.logger.error(`[PersonalDirectoryService] getPersonalContactsByCriteria failure: ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
