  /**
   * Method onRoutingUpdatedMsg
   * @private
   * @param {any} routingElem [required] xmpp msg, service part
   * @returns {void} NA
   * @memberof TelephonySipWiseEventHandler
   */
  onRoutingUpdatedMsg(routingElem) {
    this.logger.info("[TelephonySipWiseEventHandler] onRoutingUpdatedMsg : msg routing update received");
    const routingUpdatedElt = routingElem.find("routingUpdated");
    const currentDeviceId = routingUpdatedElt.find("currentDeviceId").text();
    const destinationElem = routingUpdatedElt.find("destinations");
    const destinations = [];
    const ringObj = this.telephonyService.telephonyServiceSipWise.routingData;
    if (!currentDeviceId || !destinationElem) {
      this.logger.info("[TelephonySipWiseEventHandler] onRoutingUpdatedMsg Anomaly: no current/destination elts");
      return;
    }
    ringObj.alsoOfficePhoneRingEnabled = false;
    destinationElem.find("destination").each((__index, destination) => {
      const destinationElemIter = $(destination);
      const type = destinationElemIter.attr("type");
      const deviceId = destinationElemIter.attr("deviceId");
      this.logger.info("[TelephonySipWiseEventHandler] onRoutingUpdatedMsg ITER desti / type = " + type + " deviceId = " + deviceId);
      destinations.push({ deviceId, type });
      if (type === "sip") {
        ringObj.alsoOfficePhoneRingEnabled = true;
      }
    });
    if (currentDeviceId) {
      this.telephonyService.telephonyServiceSipWise.setCurrentDevice(currentDeviceId);
    }
    if (destinations?.length) {
      this.logger.info("[TelephonySipWiseEventHandler] onRoutingUpdatedMsg  / ringing destinations nb  = " + destinations.length);
      ringObj.ringingDestinations = destinations;
      this.eventService.publish("ON_SIPWISE_ROUTING_EVENT", this.telephonyService.telephonyServiceSipWise.getCurrentDevice().type, ringObj);
    }
  }
