  /**
   * Send the retrieve Call service request to the server
   * Used by SDK (public)
   * Warning when modifying this method
   * @public
   * @param {Call} call The held call to retrieve
   * @async
   * @returns {Promise<CallRB>} Promise resolved with the held call
   * @instance
   * @function retrieveCall
   */
  async retrieveCall(call) {
    this.logger.info("[telephonyService] [TEL][API] retrieveCall callId: " + call.id + " " + call.contact.nameForLogs);
    if (this.isMixPstnWebRtcAllowed) {
      this.eventService.publish("PUT_ACTIVE_WEBRTC_CALL_OR_CONF_ON_HOLD");
    }
    const activeCall = this.getActiveCall();
    if (activeCall) {
      try {
        try {
          await this.holdCall(activeCall);
        } catch (error) {
          if (this.isOxe && error?.errorDetailsCode === 487002) {
            await this.alternateCall(activeCall, call);
            return call;
          }
          throw error;
        }
        return await this.retrieveCall(call);
      } catch (error) {
        const errorMessage = "retrieveCall failure : " + error.message;
        this.logger.error("[telephonyService] [TEL][API] - retrieveCall -  " + errorMessage);
        throw new Error(errorMessage);
      }
    } else {
      if (this.isSipWise()) {
        return this.telephonyServiceSipWise.retrieveCall(call);
      }
      try {
        const url = this.portalURL + "calls/" + encodeURIComponent(call.connectionId) + "/retrieve";
        const headers = this.authService.getPostHeader();
        const response = await fetch(url, { method: "PUT", headers });
        if (!response.ok) {
          throw response;
        }
        const responseBody = await response.json();
        const data = responseBody.data;
        this.logger.info("[telephonyService] [TEL][API] retrieveCall - success : " + anonymizer_default(call.contact.displayName) + " Call (" + call + ")");
        call.setConnectionId(data.callId);
        call.setStatus("ACTIVE" /* ACTIVE */);
        call.sendEvent("ON_CALL_UPDATED_EVENT" /* ON_CALL_UPDATED_EVENT */);
        this.eventService.publish("ON_CALL_UPDATED_EVENT", call);
        const mediaPillarCall = call.getMediaPillarCall();
        if (mediaPillarCall?.webrtcCallRef) {
          this.webrtcP2PService?.attachDistantMediaStreams(true, mediaPillarCall?.webrtcCallRef);
        }
        return call;
      } catch (error) {
        const errorInfo = await this.errorHelperService.getErrorInfo(error, "retrieveCall");
        this.logger.error(`[telephonyService] [TEL][API] ${errorInfo.message}`);
        throw errorInfo.error;
      }
    }
  }
