  async cancelForwardOnCloudIssue() {
    this.logger.info("[telephonyService] [TEL][API] cancelForwardOnCloudIssue");
    if (!this.isForwardEnabled) {
      const profileError = new Error("cancelForward failure - Not Allowed");
      profileError.status = profileError.errorDetailsCode = "403";
      this.logger.error("[telephonyService] " + profileError.message);
      throw profileError;
    }
    if (this.contactService.userContact.phonePbx) {
      try {
        const url = this.portalURL + "forwardOverflow";
        const headers = this.authService.getPostHeader();
        const data = {
          forwardType: "no_forward",
          pbxForwardType: "overflow_to_associated"
        };
        const body = JSON.stringify(data);
        const response = await fetch(url, { method: "PUT", headers, body });
        if (!response.ok) throw response;
        this.logger.info("[telephonyService] [TEL][API] cancelForwardOnCloudIssue - success");
      } catch (error) {
        const errorInfo = await this.errorHelperService.getErrorInfo(error, "cancelForwardOnCloudIssue");
        this.logger.error(`[telephonyService] [TEL][API] ${errorInfo.message}`);
        throw errorInfo.error;
      }
    }
  }
  /**
   * To know the forward Status
   * @public
   * @async
   * @returns {Promise<void>} Status promise resolved when the process is complete
   * @instance
   * @function getForwardStatus
   */
  async getForwardStatus() {
    if (!this.isForwardEnabled) {
      const profileError = new Error("getForwardStatus failure - Not Allowed");
      profileError.status = profileError.errorDetailsCode = "403";
      this.logger.error("[telephonyService] " + profileError.message);
      throw profileError;
    }
    if (this.starting || this.started) {
      if (this.isSipWise()) {
        try {
          await this.telephonyServiceSipWise.getForwardStatus();
          return;
        } catch (error) {
          const errorInfo = await this.errorHelperService.getErrorInfo(error, "getForwardStatus");
          this.logger.error(`[telephonyService] ${errorInfo.message}`);
          throw errorInfo.error;
        }
      }
      this.logger.info("[telephonyService] [TEL][API] getForwardStatus");
      try {
        let url = this.portalURL + "forward";
        let headers = this.authService.getRequestHeader();
        let response = await fetch(url, { method: "GET", headers });
        if (!response.ok) {
          throw response;
        }
        let responseBody = await response.json();
        let data = responseBody.data;
        if (data) {
          this.eventService.publish("ON_CALL_FORWARDED_EVENT", {
            "forwardType": data.forwardType,
            "forwardTo": data.pbxForwardType !== "do_not_disturb" ? data.forwardTo : "",
            "pbxForwardType": data.pbxForwardType
          });
          this.forwardObject.forwardType = data.forwardType;
          this.forwardObject.forwardTo = data.pbxForwardType !== "do_not_disturb" ? data.forwardTo : "";
          this.forwardObject.pbxForwardType = data.pbxForwardType;
          this.logger.info("[telephonyService] getForwardStatus - success - forwardType: " + data.forwardType + " forwardTo: " + data.forwardTo + " pbxForwardType: " + data.pbxForwardType);
        }
        if (this.isOxe && (this.profileService.isFeatureEnabled(this.profileService.FeaturesEnum.TELEPHONY_OXE_OVERFLOW) || this.settingsService.getBooleanSetting("forwardOnCloudIssue"))) {
          url = this.portalURL + "forwardOverflow";
          headers = this.authService.getRequestHeader();
          response = await fetch(url, { method: "GET", headers });
          if (!response.ok) {
            throw response;
          }
          responseBody = await response.json();
          data = responseBody.data;
          if (data && data.pbxForwardType === "overflow_to_associated") {
            this.forwardObject.forwardOverflowType = data.forwardType;
            this.forwardObject.forwardOverflowTo = data.forwardTo;
            this.forwardObject.pbxForwardOverflowType = data.pbxForwardType;
            this.eventService.publish("ON_CALL_FORWARDOVERFLOW_EVENT", {
              "forwardOverflowType": data.forwardType,
              "forwardOverflowTo": data.forwardTo,
              "pbxForwardOverflowType": data.pbxForwardType
            });
            this.logger.info("[telephonyService] getForwardOverflowStatus - success - forwardOverflowType: " + data.forwardOverflowType + " forwardOverflowTo: " + data.forwardOverflowTo + " pbxForwardOverflowType: " + data.pbxForwardOverflowType);
          }
        }
      } catch (error) {
        const errorInfo = await this.errorHelperService.getErrorInfo(error, "getForwardStatus");
        this.logger.error(`[telephonyService] ${errorInfo.message}`);
        throw errorInfo.error;
      }
    } else {
      throw new Error("getForwardStatus failure - Telephony not started");
    }
  }
