  /**
   * Configure the nomadic mode
   * @public
   * @param {string} phoneNumber phonenumber which will be monitored
   * @param {boolean} isUnchangeableNumber  allow to define the phonenumber like a rainbowNumber
   * @param {boolean} NotTakeIntoAccount the result won't be taken in account (above used un graphical interface)
   * @async
   * @returns {Promise<void>} Status promise resolved when the process is complete
   * @instance
   * @function nomadicLogin
   */
  async nomadicLogin(phoneNumber, isUnchangeableNumber = false, NotTakeIntoAccount = false) {
    if (!this.isNomadicEnabled || !this.nomadicObject.featureActivated) {
      const profileError = new Error("nomadicLogin failure - Not Allowed");
      profileError.status = profileError.errorDetailsCode = "403";
      this.logger.error("[telephonyService] " + profileError.message);
      throw profileError;
    }
    if (this.contactService.userContact.phonePro === phoneNumber || this.contactService.userContact.phoneProCan === phoneNumber || this.contactService.userContact.phonePbx === phoneNumber) {
      const errorMessage = "nomadicLogin failure: impossible to use its own phone number like nomadic phone";
      const errorMessageKey = "nomadicImpossibleUseOwnPhonenumber";
      this.logger.error("[telephonyService] " + errorMessage);
      throw new Error(errorMessageKey);
    }
    this.logger.info("[telephonyService] [TEL][API] nomadicLogin : " + anonymizer_default(phoneNumber));
    NotTakeIntoAccount = NotTakeIntoAccount || false;
    isUnchangeableNumber = isUnchangeableNumber || false;
    this.nomadicAnswerNotTakedIntoAccount = NotTakeIntoAccount;
    try {
      let contact = this.contactService.getContactFromCacheContainsPhoneNumber(phoneNumber);
      if (!contact) {
        contact = await this.contactService.getOrCreateContact(null, phoneNumber);
      }
      const phoneInfo = this.getPhoneInfo(contact, phoneNumber);
      const url = this.portalURL + "nomadic/login";
      const data = {
        destinationExtNumber: phoneInfo.longNumber,
        destinationIntNumber: phoneInfo.internalNumber,
        destinationShortNumber: phoneInfo.shortNumber,
        destinationRainbowNumber: isUnchangeableNumber ? phoneNumber : "",
        destinationPbxId: phoneInfo.pbxId,
        destinationDisplayName: contact.displayName,
        destinationCountry: contact.country
      };
      const body = JSON.stringify(data);
      const headers = this.authService.getPostHeader();
      const response = await fetch(url, { method: "PUT", headers, body });
      if (!response.ok) throw response;
      this.logger.info("[telephonyService] [TEL][API] nomadicLogin - success");
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "nomadicLogin");
      this.logger.error(`[telephonyService] [TEL][API] ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
