  /**
   * To know the nomadic Status
   * @public
   * @async
   * @returns {Promise<void>} Status promise resolved when the process is complete
   * @instance
   * @function getNomadicStatus
   */
  async getNomadicStatus() {
    if (this.isSipWise()) {
      this.logger.info("[telephonyService] getNomadicStatus -- SipWise bypass Nomadic");
      return;
    }
    if (!this.isNomadicEnabled) {
      const profileError = new Error("getNomadicStatus failure - Not Allowed");
      profileError.status = profileError.errorDetailsCode = "403";
      this.logger.error("[telephonyService] " + profileError.message);
      throw profileError;
    }
    if (this.starting || this.started) {
      try {
        const url = this.portalURL + "nomadic";
        const headers = this.authService.getRequestHeader();
        const response = await fetch(url, { method: "GET", headers });
        if (!response.ok) {
          throw response;
        }
        const responseBody = await response.json();
        const data = responseBody.data;
        this.updateNomadicData(data);
      } catch (error) {
        const errorInfo = await this.errorHelperService.getErrorInfo(error, "getNomadicStatus");
        this.logger.error(`[telephonyService] ${errorInfo.message}`);
        throw errorInfo.error;
      }
    } else {
      throw new Error("getNomadicStatus failure - Telephony not started");
    }
  }
