  //RQ6394 - RQ7175 ++
  oxoMultiCallMode() {
    if (!this.isOxo) {
      return false;
    }
    let result = false;
    result = this.profileService.isFeatureEnabled(this.profileService.FeaturesEnum.TELEPHONY_OXO_MULTICALL);
    result = result && this.agentStatus.featureOXOMULTICALL;
    const sipWiseFlagHack = this.settingsService.getSetting("sipWiseMode");
    result = result || sipWiseFlagHack === "RQ6394";
    return result;
  }
  //RQ6394 - RQ7175 --
  sipWiseMode() {
    let mode = this.settingsService.getSetting("sipWiseMode");
    if (!this.sipWise) {
      mode = "false";
    }
    return mode;
  }
