  async resetAllSipWiseCall() {
    if (this.isSipWise()) {
      const iq = $iq({ type: "set", to: this.userJidTel + "/pcg2" }).c("telephony", { xmlns: "urn:xmpp:pbxagent:telephony:1" }).c("service").c("deleteCalls", { forced: "true" });
      try {
        const data = await this.xmppService.sendIQ(iq, 6e4);
        this.logger.error("[telephonyService] resetAllSipWiseCall : try to reset all ghost calls !" + data);
      } catch (error) {
        const errorMessage = "resetAllSipWiseCall failure : " + error.message;
        this.logger.error("[telephonyService]" + errorMessage);
      }
    }
  }
