  async oxopbxsUpdateIndividualPassword(newPassword) {
    try {
      const url = "${config.restServerUrl}/api/rainbow/oxopbxprovisioning/v1.0/oxopbxs/" + this.contactService.userContact.systemId + "/subscribers/" + this.contactService.userContact.dbId + "/password";
      const reqData = { password: newPassword };
      const body = JSON.stringify(reqData);
      const headers = this.authService.getPostHeader();
      const response = await fetch(url, { method: "PUT", headers, body });
      if (!response.ok) throw response;
      this.logger.info("[telephonyService] oxopbxsUpdateIndividualPassword : success");
      const responseData = (await response.json()).data;
      return responseData;
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "oxopbxsUpdateIndividualPassword");
      this.logger.error(`[telephonyService] ${errorInfo.message}`);
      throw errorInfo.error;
    }
  }
