  async createWebinar(webinar, addToCache = true) {
    try {
      this.createInProgress = true;
      const url = `${config.restServerUrl}/api/rainbow/webinar/v1.0/webinars`;
      const headers = this.authService.getPostHeader();
      const body = webinar.getData();
      const response = await fetch(url, { method: "POST", headers, body });
      if (!response.ok) throw response;
      const data = (await response.json()).data;
      webinar.updateFromData(data);
      this.updateRoles(webinar);
      await this.getWebinarRooms(webinar);
      if (addToCache) this.addWebinarToCache(webinar);
      this.createInProgress = false;
      this.logger.info(`[WebinarService] createWebinar -- ${webinar.id} -- success`);
      return webinar;
    } catch (error) {
      const errorInfo = await this.errorHelperService.getErrorInfo(error, "createWebinar");
      this.logger.error(`[WebinarService] ${errorInfo.message}`);
      this.createInProgress = false;
      throw errorInfo.error;
    }
  }
